{"implementation": "def solve(case):
    lines = case['lines']
    trajectory = []
    valid = True
    error_line = None
    prev_type = None
    for idx, line in enumerate(lines, start=1):
        if ': ' in line:
            typ, content = line.split(': ', 1)
        else:
            typ, content = line, ''
        trajectory.append({'type': typ, 'content': content})
        if not valid:
            continue
        if idx == 1:
            if typ != 'Thought':
                valid = False
                error_line = idx
        else:
            if prev_type == 'Thought':
                if typ not in ('Action', 'Final'):
                    valid = False
                    error_line = idx
            elif prev_type == 'Action':
                if typ != 'Observation':
                    valid = False
                    error_line = idx
            elif prev_type == 'Observation':
                if typ not in ('Thought', 'Final'):
                    valid = False
                    error_line = idx
            elif prev_type == 'Final':
                valid = False
                error_line = idx
            else:
                valid = False
                error_line = idx
        prev_type = typ
    if valid and (not trajectory or trajectory[-1]['type'] != 'Final'):
        valid = False
        error_line = len(lines)
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}"}
